  const [plate,setPlate]=useState("");const [spot,setSpot]=useState("");
  const [date,setDate]=useState("");const [time,setTime]=useState("");
  const [busy,setBusy]=useState(false);const [done,setDone]=useState(false);const [confetti,setConfetti]=useState(false);
  const ok = cwType&&name&&apt&&plate&&date&&time;
  const reset = ()=>{setCwType("");setName("");setApt("");setPlate("");setSpot("");setDate("");setTime("");setDone(false);};
